// Generated by scripts/sync-compose.ts from deploy/docker-compose.yml. Do not edit by hand.
export const composeFile = "# ARTEL self-hosted stack. Needs Docker Compose 2.23.1 or later (the Caddy configuration below is inlined).\n#\n# Easiest: run install.sh, which saves this file and fills in the secrets below.\n# By hand: save this file, replace every CHANGE_ME below (generate each with: openssl rand -hex 32),\n# then run: docker compose up -d   and open the public URL. The first account to sign up becomes the admin;\n# the admin page sets the OpenRouter key.\n#\n# This file holds secrets once you edit it. Do not commit it or share it. Back it up: if\n# x-secrets-key is lost or changed, the OpenRouter key saved on the admin page cannot be read.\n# The build sections only matter in a clone of the repository: `docker compose build orchestration agent-server`.\n\nname: artel\n\n# ---- Edit these. Each value is written once and used by the services that need it. ----\n# Public URL of the console, no trailing slash. To change the host port or name, change the URL and the\n# published ports of the proxy service (and the Caddy site addresses at the bottom) together.\nx-public-url: &public_url http://localhost:8088\n# URL of the admin page. Keep the same host name as the public URL so one login works on both.\nx-admin-url: &admin_url http://localhost:8090\n# Signs session tokens. At least 32 bytes: the server refuses to start with the placeholder.\nx-jwt-secret: &jwt_secret CHANGE_ME\n# Encrypts the OpenRouter key saved on the admin page. Never change it after first start.\nx-secrets-key: &secrets_key CHANGE_ME\nx-db-password: &db_password CHANGE_ME\n# MinIO root user and password (object storage for uploads), at least 3 and 8 characters.\nx-s3-access-key: &s3_access_key CHANGE_ME\nx-s3-secret-key: &s3_secret_key CHANGE_ME\n# Optional. A single OpenRouter key covers every model; the admin page can set it instead and wins.\nx-openrouter-api-key: &openrouter_api_key \"\"\n\nx-restart: &restart\n  restart: unless-stopped\n\nservices:\n  postgres:\n    <<: *restart\n    # Must be the pgvector image: a Flyway migration runs CREATE EXTENSION vector.\n    image: pgvector/pgvector:pg16\n    environment:\n      POSTGRES_DB: artel\n      POSTGRES_USER: artel\n      POSTGRES_PASSWORD: *db_password\n    volumes:\n      - postgres-data:/var/lib/postgresql/data\n    healthcheck:\n      test: [\"CMD-SHELL\", \"pg_isready -U artel -d artel\"]\n      interval: 5s\n      timeout: 5s\n      retries: 20\n\n  redis:\n    <<: *restart\n    # Holds only five-minute SDK login codes, so persistence stays off on purpose.\n    # Valkey, not Redis: current Redis 7.x tags are RSALv2/SSPLv1, which does not fit an AGPL-3.0 release.\n    image: valkey/valkey:8.1.10-alpine\n    command: [\"valkey-server\", \"--save\", \"\", \"--appendonly\", \"no\"]\n    healthcheck:\n      test: [\"CMD\", \"valkey-cli\", \"ping\"]\n      interval: 5s\n      timeout: 3s\n      retries: 20\n\n  minio:\n    <<: *restart\n    # Docker Hub no longer serves minio/minio, so this is the Chainguard build.\n    image: cgr.dev/chainguard/minio:latest\n    command: [\"server\", \"/data\", \"--console-address\", \":9001\"]\n    environment:\n      MINIO_ROOT_USER: *s3_access_key\n      MINIO_ROOT_PASSWORD: *s3_secret_key\n    depends_on:\n      minio-init:\n        condition: service_completed_successfully\n    volumes:\n      - minio-data:/data\n    # No published port. Browsers reach MinIO through the proxy on the public URL,\n    # and the other services reach it over the compose network.\n    expose:\n      - \"9000\"\n\n  minio-init:\n    # MinIO serves every top-level directory of its data volume as a bucket, so this creates the\n    # bucket \"artel\" on first start and exits. The bucket name must not be api, oauth2, login, ws,\n    # assets, projects or account: the proxy routes those paths to the console and the API.\n    # 65532 is the user the MinIO image runs as.\n    image: busybox:1.37\n    command: [\"sh\", \"-c\", \"mkdir -p /data/artel && chown 65532:65532 /data/artel\"]\n    volumes:\n      - minio-data:/data\n\n  orchestration:\n    <<: *restart\n    image: ghcr.io/project-artel/orchestration:develop\n    build:\n      context: ../artel-orchestration-server\n      dockerfile: ../deploy/Dockerfile.orchestration\n    depends_on:\n      postgres:\n        condition: service_healthy\n      redis:\n        condition: service_healthy\n      minio:\n        condition: service_started\n    environment:\n      DB_HOST: postgres\n      DB_PORT: \"5432\"\n      DB_NAME: artel\n      DB_USERNAME: artel\n      DB_PASSWORD: *db_password\n      DB_SSL_MODE: disable\n      REDIS_URL: redis://redis:6379\n      ARTEL_INTERNAL_API_PORT: \"8081\"\n      # The agent server serves every route under /internal, and the clients append /extract, /embed,\n      # /sessions and so on to this base URL, so the prefix belongs here.\n      ARTEL_AGENT_BASE_URL: http://agent-server:8000/internal\n      ARTEL_AGENT_WS_BASE_URL: ws://agent-server:8000/internal\n      # The server's application.yml sets org.springframework.web to DEBUG, which logs a line for every\n      # request including each 401, 403 and 404. Keep production logs at INFO.\n      LOGGING_LEVEL_ORG_SPRINGFRAMEWORK_WEB: INFO\n      LOGGING_LEVEL_ORG_SPRINGFRAMEWORK_WEB_REACTIVE: INFO\n      # The console origin is always allowed; this adds the admin page.\n      ARTEL_HOME_URL: *public_url\n      ARTEL_ALLOWED_ORIGINS: *admin_url\n      ARTEL_JWT_SECRET: *jwt_secret\n      ARTEL_SECRETS_KEY: *secrets_key\n      # Set to true only when the public URL is https, so cookies are sent over TLS only.\n      ARTEL_SECURE_COOKIE: \"false\"\n      # The first account to sign up becomes the admin. After that, public signup is closed unless true.\n      ARTEL_SIGNUP_OPEN: \"false\"\n      # With false, a GitHub account signs in only when an admin created a user with the same email.\n      ARTEL_GITHUB_SIGNUP_OPEN: \"false\"\n      # Login rate limit: failures per email or per client address inside the window before a 429.\n      ARTEL_LOGIN_MAX_FAILURES: \"10\"\n      ARTEL_LOGIN_FAILURE_WINDOW: PT15M\n      ARTEL_LOGIN_ADDRESS_MAX_FAILURES: \"100\"\n      OPENROUTER_API_KEY: *openrouter_api_key\n      # Optional GitHub login. The button is hidden unless both are set.\n      # Callback URL: <public URL>/login/oauth2/code/github\n      GITHUB_CLIENT_ID: \"\"\n      GITHUB_CLIENT_SECRET: \"\"\n      ARTEL_S3_BUCKET: artel\n      ARTEL_S3_REGION: us-east-1\n      # The server's own S3 calls go to MinIO over the compose network. Presigned URLs that the browser\n      # opens are written for the public URL, and the proxy forwards /artel/ to MinIO unchanged.\n      ARTEL_S3_ENDPOINT: http://minio:9000\n      ARTEL_S3_PRESIGN_ENDPOINT: *public_url\n      ARTEL_S3_ACCESS_KEY: *s3_access_key\n      ARTEL_S3_SECRET_KEY: *s3_secret_key\n    # 8080 is reached only through the reverse proxy and 8081 only from this network.\n    expose:\n      - \"8080\"\n      - \"8081\"\n\n  agent-server:\n    <<: *restart\n    image: ghcr.io/project-artel/agent:develop\n    build:\n      context: ../artel-agent-server\n      target: runtime\n    environment:\n      APP_PORT: \"8000\"\n      APP_ENV: production\n      # The key from the admin page wins; this is the fallback.\n      OPENROUTER_API_KEY: *openrouter_api_key\n      # Internal port: the unauthenticated /internal/** API, reached only over the compose network.\n      ORCHESTRATION_BASE_URL: http://orchestration:8081\n      LANGSMITH_TRACING: \"false\"\n    expose:\n      - \"8000\"\n\n  admin-page:\n    <<: *restart\n    image: ghcr.io/project-artel/admin:main\n    environment:\n      # The container replaces a placeholder in the bundle with these at start.\n      VITE_ORCHESTRATION_URL: *admin_url\n      VITE_HOME_URL: *public_url\n    expose:\n      - \"8080\"\n\n  artel-home:\n    <<: *restart\n    image: ghcr.io/project-artel/console:develop\n    environment:\n      VITE_ORCHESTRATION_URL: *public_url\n    expose:\n      - \"8080\"\n\n  proxy:\n    <<: *restart\n    image: caddy:2-alpine\n    depends_on:\n      - orchestration\n      - admin-page\n      - artel-home\n    configs:\n      - source: caddyfile\n        target: /etc/caddy/Caddyfile\n    volumes:\n      - caddy-data:/data\n      - caddy-config:/config\n    # Host ports: console, TLS (used only when a Caddy site address is a host name), admin page.\n    ports:\n      - \"8088:80\"\n      - \"8443:443\"\n      - \"8090:8090\"\n\n# Caddy configuration. It cannot read the values at the top, so edit the ports above and the public URL together.\n# A host name instead of :80 or :8090 makes Caddy fetch a TLS certificate. The two sites are two origins\n# because each frontend image serves its bundle from the root path; each browser calls only its own origin.\n# The orchestration internal port 8081 is deliberately not routed.\nconfigs:\n  caddyfile:\n    content: |\n      :80 {\n        encode zstd gzip\n\n        # Presigned upload and download URLs go straight to MinIO. They are signed over the exact path\n        # and Host header, so this route must not rewrite either.\n        handle /artel/* {\n          reverse_proxy minio:9000\n        }\n\n        @orchestration path /api/* /oauth2/* /login/oauth2/* /ws/*\n        handle @orchestration {\n          # flush_interval -1 keeps server-sent event streams from being buffered.\n          reverse_proxy orchestration:8080 {\n            flush_interval -1\n          }\n        }\n\n        handle {\n          reverse_proxy artel-home:8080\n        }\n      }\n\n      :8090 {\n        encode zstd gzip\n\n        @orchestration path /api/* /oauth2/* /login/oauth2/* /ws/*\n        handle @orchestration {\n          reverse_proxy orchestration:8080 {\n            flush_interval -1\n          }\n        }\n\n        handle {\n          reverse_proxy admin-page:8080\n        }\n      }\n\n\nvolumes:\n  postgres-data:\n  minio-data:\n  caddy-data:\n  caddy-config:"
